BLOQUES['test_board_driver'] = r'''
#!/usr/bin/env python3
"""test_board_driver.py — BE-CF14: toda familia de gypsum board de canon entra al driver de finishing (compound / tape),
salvo cement board, ballistic panel, sheathing exterior y el 1" shaftliner (BE-CR02: liner del lado del shaft, sin finishing)."""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import canon, accesorios
fuera = ("cement", "ballistic", "EXTERIOR", "glass mat", "FRT", "1/4", "shaftliner")
gyp = [f for f in canon.BOARD_FAM.values() if "gyp" in f.lower() and not any(x in f for x in fuera)]
falta = [f for f in gyp if f not in accesorios.BOARD_DRIVER]
assert not falta, f"familias de gypsum board fuera del driver de finishing: {falta}"
print("test_board_driver OK")
'''
